import type { PoolClient } from "pg";
/**
 * Price records of equipment (ADR 0006, shared/equipmentPrices.ts), outside `equipment_catalog`.
 *
 * - Insert-only per organization; a void sets `voided_at`/`voided_by_id` and never deletes the row.
 * - `id` is generated by the client (`po-<uuid>`) and is unique per organization: replays are idempotent.
 * - `seq` is the server insertion order; the current generic price is the non-voided `generic` row with the highest
 *   `seq`, never the client clock.
 * - `equipment_id` has no foreign key: equipment created offline can arrive after its prices, and records of a
 *   deleted equipment stay (readers hide them).
 * - `project_id` stores no proposal or client name: the name is resolved when reading.
 * - Starts empty: no records are created from the existing offers.
 */
export async function equipmentPriceObservations(
  client: PoolClient,
): Promise<void> {
  await client.query(`
    CREATE TABLE IF NOT EXISTS equipment_price_observations (
      organization_id VARCHAR(64) NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
      id VARCHAR(40) NOT NULL CHECK (id ~ '^po-[0-9a-f-]{36}$'),
      seq BIGSERIAL NOT NULL UNIQUE,
      equipment_id VARCHAR(64) NOT NULL,
      kind VARCHAR(16) NOT NULL CHECK (kind IN ('observation','generic')),
      price_usd NUMERIC NOT NULL CHECK (price_usd >= 0),
      original_currency VARCHAR(3) CHECK (original_currency IN ('USD','DOP')),
      original_price NUMERIC CHECK (original_price >= 0),
      source VARCHAR(16) NOT NULL CHECK (source IN ('supplier_offer','ai_scan','proposal','manual','agent')),
      supplier_name VARCHAR(255),
      supplier_offer_id VARCHAR(128),
      project_id VARCHAR(128),
      derived_from_id VARCHAR(40),
      observed_at TIMESTAMPTZ NOT NULL CHECK (observed_at >= TIMESTAMPTZ '2020-01-01T00:00:00Z'),
      created_by_id VARCHAR(64) REFERENCES users(id) ON DELETE SET NULL,
      created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
      voided_at TIMESTAMPTZ,
      voided_by_id VARCHAR(64) REFERENCES users(id) ON DELETE SET NULL,
      PRIMARY KEY (organization_id, id),
      CONSTRAINT equipment_price_generic_positive CHECK (kind <> 'generic' OR price_usd > 0),
      CONSTRAINT equipment_price_project_only_proposal CHECK (project_id IS NULL OR source = 'proposal'),
      CONSTRAINT equipment_price_derived_only_generic CHECK (derived_from_id IS NULL OR kind = 'generic')
    );
    CREATE INDEX IF NOT EXISTS equipment_price_observations_history_idx
      ON equipment_price_observations (organization_id, equipment_id, seq DESC);
    CREATE INDEX IF NOT EXISTS equipment_price_observations_kind_idx
      ON equipment_price_observations (organization_id, kind, equipment_id, seq DESC);
  `);
}
